package io.github.jhipster.sample.web.rest.errors;

import jakarta.servlet.http.HttpServletRequest;
import java.net.URI;
import java.util.Arrays;
import java.util.List;
import java.util.stream.Collectors;
import org.apache.commons.lang3.StringUtils;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.core.annotation.AnnotatedElementUtils;
import org.springframework.core.env.Environment;
import org.springframework.dao.ConcurrencyFailureException;
import org.springframework.dao.DataAccessException;
import org.springframework.http.HttpHeaders;
import org.springframework.http.HttpStatus;
import org.springframework.http.HttpStatusCode;
import org.springframework.http.ProblemDetail;
import org.springframework.http.ResponseEntity;
import org.springframework.http.converter.HttpMessageConversionException;
import org.springframework.security.access.AccessDeniedException;
import org.springframework.security.core.AuthenticationException;
import org.springframework.validation.BindingResult;
import org.springframework.web.bind.MethodArgumentNotValidException;
import org.springframework.web.bind.annotation.ControllerAdvice;
import org.springframework.web.bind.annotation.ExceptionHandler;
import org.springframework.web.bind.annotation.ResponseStatus;
import org.springframework.web.context.request.NativeWebRequest;
import org.springframework.web.context.request.ServletWebRequest;
import org.springframework.web.context.request.WebRequest;
import org.springframework.web.servlet.mvc.method.annotation.ResponseEntityExceptionHandler;
import tech.jhipster.config.JHipsterConstants;
import tech.jhipster.web.util.HeaderUtil;

/**
 * Controller advice to translate the server side exceptions to client-friendly json structures.
 * The error response follows RFC7807 - Problem Details for HTTP APIs (https://tools.ietf.org/html/rfc7807).
 */
@ControllerAdvice
public class ExceptionTranslator extends ResponseEntityExceptionHandler {

    private static final String FIELD_ERRORS_KEY = "fieldErrors";
    private static final String MESSAGE_KEY = "message";
    private static final String PATH_KEY = "path";

    @Value("${jhipster.clientApp.name}")
    private String applicationName;

    private final Environment env;

    public ExceptionTranslator(Environment env) {
        this.env = env;
    }

    @ExceptionHandler
    public ResponseEntity<Object> handleAnyException(Throwable ex, NativeWebRequest request) {
        ProblemDetail problem = buildProblemDetail(ex, resolveStatus(ex));
        return handleExceptionInternal((Exception) wrap(ex), problem, buildHeaders(ex), HttpStatusCode.valueOf(problem.getStatus()), request);
    }

    @ExceptionHandler
    public ResponseEntity<Object> handleEmailAlreadyUsedException(
        io.github.jhipster.sample.service.EmailAlreadyUsedException ex,
        NativeWebRequest request
    ) {
        EmailAlreadyUsedException problem = new EmailAlreadyUsedException();
        return handleBadRequestAlertException(problem, request);
    }

    @ExceptionHandler
    public ResponseEntity<Object> handleUsernameAlreadyUsedException(
        io.github.jhipster.sample.service.UsernameAlreadyUsedException ex,
        NativeWebRequest request
    ) {
        return handleBadRequestAlertException(new LoginAlreadyUsedException(), request);
    }

    @ExceptionHandler
    public ResponseEntity<Object> handleInvalidPasswordException(
        io.github.jhipster.sample.service.InvalidPasswordException ex,
        NativeWebRequest request
    ) {
        InvalidPasswordException problem = new InvalidPasswordException();
        return handleExceptionInternal(problem, problem.getBody(), new HttpHeaders(), problem.getStatusCode(), request);
    }

    @ExceptionHandler
    public ResponseEntity<Object> handleBadRequestAlertException(BadRequestAlertException ex, NativeWebRequest request) {
        HttpHeaders headers = HeaderUtil.createFailureAlert(applicationName, true, ex.getEntityName(), ex.getErrorKey(), ex.getMessage());
        return handleExceptionInternal(ex, ex.getBody(), headers, ex.getStatusCode(), request);
    }

    @ExceptionHandler
    public ResponseEntity<Object> handleConcurrencyFailure(ConcurrencyFailureException ex, NativeWebRequest request) {
        ProblemDetail problem = ProblemDetail.forStatus(HttpStatus.CONFLICT);
        problem.setProperty(MESSAGE_KEY, ErrorConstants.ERR_CONCURRENCY_FAILURE);
        return handleExceptionInternal(ex, problem, new HttpHeaders(), HttpStatus.CONFLICT, request);
    }

    @Override
    protected ResponseEntity<Object> handleMethodArgumentNotValid(
        MethodArgumentNotValidException ex,
        HttpHeaders headers,
        HttpStatusCode status,
        WebRequest request
    ) {
        BindingResult result = ex.getBindingResult();
        List<FieldErrorVM> fieldErrors = result
            .getFieldErrors()
            .stream()
            .map(f ->
                new FieldErrorVM(
                    f.getObjectName().replaceFirst("DTO$", ""),
                    f.getField(),
                    StringUtils.isNotBlank(f.getDefaultMessage()) ? f.getDefaultMessage() : f.getCode()
                )
            )
            .collect(Collectors.toList());

        ProblemDetail problem = ProblemDetail.forStatus(HttpStatus.BAD_REQUEST);
        problem.setType(ErrorConstants.CONSTRAINT_VIOLATION_TYPE);
        problem.setTitle("Method argument not valid");
        problem.setProperty(MESSAGE_KEY, ErrorConstants.ERR_VALIDATION);
        problem.setProperty(FIELD_ERRORS_KEY, fieldErrors);
        return handleExceptionInternal(ex, problem, headers, HttpStatus.BAD_REQUEST, request);
    }

    /**
     * Post-process every problem payload to add the type, the path and the message key for the front-end if needed.
     */
    @Override
    protected ResponseEntity<Object> handleExceptionInternal(
        Exception ex,
        Object body,
        HttpHeaders headers,
        HttpStatusCode statusCode,
        WebRequest request
    ) {
        ResponseEntity<Object> entity = super.handleExceptionInternal(ex, body, headers, statusCode, request);
        if (entity == null || !(entity.getBody() instanceof ProblemDetail problem)) {
            return entity;
        }
        if (problem.getType() == null || ProblemDetail.forStatus(statusCode).getType().equals(problem.getType())) {
            problem.setType(ErrorConstants.DEFAULT_TYPE);
        }
        if (problem.getTitle() == null) {
            HttpStatus resolved = HttpStatus.resolve(statusCode.value());
            if (resolved != null) {
                problem.setTitle(resolved.getReasonPhrase());
            }
        }
        if (request instanceof ServletWebRequest servletRequest) {
            HttpServletRequest nativeRequest = servletRequest.getRequest();
            problem.setProperty(PATH_KEY, nativeRequest.getRequestURI());
        } else {
            problem.setProperty(PATH_KEY, StringUtils.EMPTY);
        }
        if (problem.getProperties() == null || !problem.getProperties().containsKey(MESSAGE_KEY)) {
            problem.setProperty(MESSAGE_KEY, "error.http." + problem.getStatus());
        }
        return entity;
    }

    private Throwable wrap(Throwable ex) {
        return ex instanceof Exception ? ex : new RuntimeException(ex);
    }

    private HttpStatusCode resolveStatus(Throwable ex) {
        if (ex instanceof AccessDeniedException) {
            return HttpStatus.FORBIDDEN;
        }
        if (ex instanceof AuthenticationException) {
            return HttpStatus.UNAUTHORIZED;
        }
        ResponseStatus annotation = AnnotatedElementUtils.findMergedAnnotation(ex.getClass(), ResponseStatus.class);
        if (annotation != null) {
            return annotation.code();
        }
        return HttpStatus.INTERNAL_SERVER_ERROR;
    }

    private HttpHeaders buildHeaders(Throwable ex) {
        return new HttpHeaders();
    }

    private ProblemDetail buildProblemDetail(Throwable ex, HttpStatusCode status) {
        ProblemDetail problem = ProblemDetail.forStatus(status);
        problem.setType(ErrorConstants.DEFAULT_TYPE);
        HttpStatus resolved = HttpStatus.resolve(status.value());
        String reasonPhrase = resolved != null ? resolved.getReasonPhrase() : null;
        problem.setTitle(reasonPhrase);

        ResponseStatus annotation = AnnotatedElementUtils.findMergedAnnotation(ex.getClass(), ResponseStatus.class);
        if (annotation != null && StringUtils.isNotBlank(annotation.reason())) {
            problem.setTitle(annotation.reason());
            return problem;
        }

        boolean production = Arrays.asList(env.getActiveProfiles()).contains(JHipsterConstants.SPRING_PROFILE_PRODUCTION);
        if (production) {
            if (ex instanceof HttpMessageConversionException) {
                problem.setDetail("Unable to convert http message");
                return problem;
            }
            if (ex instanceof DataAccessException) {
                problem.setDetail("Failure during data access");
                return problem;
            }
            if (containsPackageName(ex.getMessage())) {
                problem.setDetail("Unexpected runtime exception");
                return problem;
            }
        }
        problem.setDetail(ex.getMessage());
        return problem;
    }

    private boolean containsPackageName(String message) {
        // This list is for sure not complete
        return StringUtils.containsAny(message, "org.", "java.", "net.", "jakarta.", "javax.", "com.", "io.", "de.", "io.github.jhipster.sample");
    }
}
